let AUTOTRAIN=null;
async function autoTrain(force){if(MODE==="mock"&&!force)return;   // the demo already starts with trained agents; training there only froze the buttons
 const last=+LS.get("pt_autotrain_at_"+MODE)||0;if(!force&&Date.now()-last<3*24*3600e3)return;if(AUTOTRAIN!=null||autoTrain.wait)return;autoTrain.wait=1;holdLoops=true;
  // only start when nothing is mid-flight: a live scan finishing inside the training simulation used to corrupt the account and jam the scanner
  for(let i=0;i<1200&&(busy||busyF||busyL||busyS||busyUI);i++)await new Promise(r=>setTimeout(r,100));
  autoTrain.wait=0;if(busy||busyF||busyL||busyS||busyUI){holdLoops=false;setTimeout(()=>autoTrain(force),600e3);return}
  AUTOTRAIN=0;
  try{await trainAgents(3,f=>{AUTOTRAIN=f;const el=$("chip");if(el){el.className="st dim";el.textContent="Training "+Math.round(f*100)+"%";el.title="Agents practise in a simulation. No money is used."}});LS.set("pt_autotrain_at_"+MODE,Date.now());save();ev("info","auto_train","","agents practised 3 simulated days (no money used)")}catch(e){console.error(e)}finally{holdLoops=false;AUTOTRAIN=null;render()}}
let holdLoops=false,ffUntil=0,tab="home",range=0,q="",sortBy="pct",filt="all",ffilt="all",openRows=new Set(),openFeed=new Set(),timers=[],busyUI=false,scrubF=null;
