function tweenEq(v){const el=$("eq");if(shownEq==null||matchMedia("(prefers-reduced-motion:reduce)").matches||Math.abs(v-shownEq)<0.005){shownEq=v;el.textContent=fmt(v);return}const from=shownEq,t0=performance.now();cancelAnimationFrame(eqRaf);const step=n=>{const k=Math.max(0,Math.min(1,(n-t0)/450)),e=1-Math.pow(1-k,3);shownEq=from+(v-from)*e;el.textContent=fmt(shownEq);if(k<1)eqRaf=requestAnimationFrame(step)};eqRaf=requestAnimationFrame(step)}
